import { A, L } from "./helpers.mjs";

export const lessons = [
  L(33, "A subquery is a query inside another query. A scalar subquery returns one single value, so it can go anywhere a value can.", [
    "Write it in brackets: WHERE salary > (SELECT AVG(salary) FROM employees).",
    "It runs first, and its result is used in the outer query.",
    "It's handy in SELECT too, for showing an overall figure on each row.",
    "If it finds no rows, it returns NULL, which is useful when a problem asks for NULL.",
  ], "staff", "SELECT name, salary\nFROM employees\nWHERE salary > (SELECT AVG(salary) FROM employees);", "The subquery calculates the average once, and the outer query keeps people above it."),
  L(34, "A subquery can provide a list to filter with. IN, NOT IN, and EXISTS are the main tools.", [
    "WHERE id IN (SELECT ...) keeps rows found in the list.",
    "NOT IN returns nothing if the list contains a NULL, because every comparison becomes unknown.",
    "Protect NOT IN by filtering NULLs inside the subquery.",
    "EXISTS checks whether a subquery finds any row, and NULLs don't affect it.",
  ], "staff", "SELECT name\nFROM employees\nWHERE id NOT IN (SELECT manager_id FROM employees WHERE manager_id IS NOT NULL);", "This finds employees who manage no one. Without the IS NOT NULL filter, it would return nothing."),
  L(35, "A subquery in FROM acts like a temporary table, so you can query a result you've already calculated.", [
    "Write FROM (SELECT ...) alias. Give it an alias if you want to refer to it.",
    "It's useful when you need to aggregate an aggregate, such as an average of totals.",
    "It's also a way to filter on a calculated column.",
    "You can join it to other tables.",
  ], "shop", "SELECT ROUND(AVG(order_units), 2) AS avg_units\nFROM (SELECT order_id, SUM(quantity) AS order_units\n      FROM order_items\n      GROUP BY order_id);", "The inner query gives one total per order, and the outer query averages those totals."),
  L(36, "A correlated subquery refers to the current row of the outer query, so it runs once for each row.", [
    "It connects through a table alias: WHERE e.salary > (SELECT AVG(salary) FROM employees x WHERE x.department_id = e.department_id).",
    "Use it to compare each row with its own group.",
    "EXISTS is usually correlated.",
    "It can run slowly on very large tables, as it repeats per row.",
  ], "staff", "SELECT e.name, e.salary\nFROM employees e\nWHERE e.salary > (\n  SELECT AVG(x.salary) FROM employees x WHERE x.department_id = e.department_id\n);", "Each employee is compared with the average of their own department."),
  L(37, "A CTE names a step of your query with WITH, so complex logic reads from top to bottom.", [
    "WITH name AS (SELECT ...) defines a step, and the main query uses it like a table.",
    "Add more steps with commas, and later steps can use earlier ones.",
    "A CTE exists only for that one query.",
    "They're usually easier to read than nested subqueries.",
  ], "shop", "WITH order_totals AS (\n  SELECT order_id, SUM(quantity) AS units\n  FROM order_items\n  GROUP BY order_id\n)\nSELECT o.customer_id, SUM(t.units) AS units\nFROM orders o\nJOIN order_totals t ON t.order_id = o.id\nGROUP BY o.customer_id;", "Totalling per order comes first, then the main query adds those totals per customer."),
  L(38, "UNION stacks the results of two queries, one on top of the other.", [
    "Both queries must return the same number of columns in a matching order.",
    "UNION removes duplicate rows, and UNION ALL keeps them.",
    "Column names come from the first query.",
    "In SQLite, ORDER BY goes once at the very end, and you can't put brackets around each branch.",
  ], "shop", "SELECT name, 'Customer' AS kind FROM customers\nUNION ALL\nSELECT name, 'Product' FROM products\nORDER BY kind, name;", "This combines two lists into one, with a label showing where each row came from."),
  L(39, "INTERSECT and EXCEPT compare two results as sets.", [
    "INTERSECT keeps rows found in both results.",
    "EXCEPT keeps rows from the first result that aren't in the second.",
    "Both remove duplicates and need matching columns.",
    "Unlike NOT IN, EXCEPT treats NULLs as equal, so it isn't caught out by them.",
  ], "shop", "SELECT id FROM customers\nEXCEPT\nSELECT customer_id FROM orders;", "This finds customer ids that never appear in orders, a neat alternative to a join."),
];

export const assignments = [
  A("s33-01", "staff", "Above average", "Show the name and salary of employees earning more than the average salary. Replace the ___ with a subquery.", "AVG(salary) goes in brackets.", "SELECT name, salary FROM employees WHERE salary > (SELECT AVG(salary) FROM employees);", [["SELECT name, salary FROM employees WHERE salary > AVG(salary);", "An aggregate can't go directly in WHERE"], ["SELECT name, salary FROM employees WHERE salary < (SELECT AVG(salary) FROM employees);", "Finds those below"]], { starter: "SELECT name, salary\nFROM employees\nWHERE salary > ___;", recalls: [19] }),
  A("s33-02", "bookshop", "Most expensive book", "Show the title of the book with the highest price, using a subquery.", "Find MAX(price), then match it.", "SELECT title FROM books WHERE price = (SELECT MAX(price) FROM books);", [["SELECT title FROM books WHERE price = (SELECT MIN(price) FROM books);", "Finds the cheapest"], ["SELECT title FROM books;", "Shows every book"]], { recalls: [19] }),
  A("s33-03", "staff", "Difference from average", "Show each employee's name and salary minus the overall average, rounded to 2 decimals, as difference.", "A subquery can go in SELECT.", "SELECT name, ROUND(salary - (SELECT AVG(salary) FROM employees), 2) AS difference FROM employees;", [["SELECT name, salary AS difference FROM employees;", "Doesn't subtract"], ["SELECT name, ROUND((SELECT AVG(salary) FROM employees) - salary, 2) AS difference FROM employees;", "Subtracts the wrong way round"]], { recalls: [12, 13] }),
  A("s33-04", "shop", "Share of products", "Show each category and its share of all products as a percentage, rounded to 1 decimal, as share.", "Divide by a subquery counting all products.", "SELECT category, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM products), 1) AS share FROM products GROUP BY category;", [["SELECT category, ROUND(COUNT(*) * 100 / (SELECT COUNT(*) FROM products), 1) AS share FROM products GROUP BY category;", "Integer division loses decimals"], ["SELECT category, COUNT(*) AS share FROM products GROUP BY category;", "A count isn't a share"]], { recalls: [12, 13], alt: "+ INSERT INTO products VALUES (10, 'Vase', 'Home', 5.0, 2.0);" }),
  A("s33-05", "staff", "When there's no answer", "Show the highest salary below 30000 as salary. When none exists, the result should be one row containing NULL.", "A scalar subquery returns NULL when it finds nothing, but MAX alone does too.", "SELECT MAX(salary) AS salary FROM employees WHERE salary < 30000;", [["SELECT salary FROM employees WHERE salary < 30000 ORDER BY salary DESC LIMIT 1;", "Returns no rows instead of NULL"], ["SELECT MIN(salary) AS salary FROM employees WHERE salary < 30000;", "Finds the lowest"]], { recalls: [19], alt: "+ UPDATE employees SET salary = 29000 WHERE id = 14; UPDATE employees SET salary = 20000 WHERE id = 15;" }),
  A("s33-06", "staff", "Fix the comparison", "This should show employees earning the top salary, but it fails because the subquery returns a whole column. Fix it.", "= needs a single value, so use MAX.", "SELECT name FROM employees WHERE salary = (SELECT MAX(salary) FROM employees);", [["SELECT name FROM employees WHERE salary IN (SELECT salary FROM employees);", "Keeps everyone"], ["SELECT name FROM employees WHERE salary > (SELECT MAX(salary) FROM employees);", "Nothing beats the maximum"]], { starter: "SELECT name\nFROM employees\nWHERE salary = (SELECT salary FROM employees WHERE);" }),
  A("s33-07", "app", "Above average session", "Show the id and minutes of sessions longer than the average session.", "Compare with the overall average.", "SELECT id, minutes FROM sessions WHERE minutes > (SELECT AVG(minutes) FROM sessions);", [["SELECT id, minutes FROM sessions WHERE minutes >= (SELECT MAX(minutes) FROM sessions);", "Finds only the longest"], ["SELECT id, minutes FROM sessions WHERE minutes < (SELECT AVG(minutes) FROM sessions);", "Finds shorter ones"]], { recalls: [19] }),
  A("s33-08", "staff", "Second-highest salary", "Show the second-highest different salary as salary. If there isn't one, return one row containing NULL.", "Wrap a query with OFFSET in a scalar subquery.", "SELECT (SELECT DISTINCT salary FROM employees ORDER BY salary DESC LIMIT 1 OFFSET 1) AS salary;", [["SELECT DISTINCT salary FROM employees ORDER BY salary DESC LIMIT 1 OFFSET 1;", "Returns no row instead of NULL"], ["SELECT (SELECT salary FROM employees ORDER BY salary DESC LIMIT 1 OFFSET 1) AS salary;", "Ties can repeat the top salary"]], { recalls: [19], alt: "UPDATE employees SET salary = 50000;" }),

  A("s34-01", "shop", "Customers with orders", "Show the name of customers who've placed an order, using IN. Replace the ___.", "The subquery lists customer_id from orders.", "SELECT name FROM customers WHERE id IN (SELECT customer_id FROM orders);", [["SELECT name FROM customers WHERE id NOT IN (SELECT customer_id FROM orders);", "Finds those without"], ["SELECT name FROM customers WHERE id IN (SELECT id FROM orders);", "Uses the order's id"]], { starter: "SELECT name\nFROM customers\nWHERE id IN (___);", recalls: [8] }),
  A("s34-02", "shop", "Products sold", "Show the name of products that appear in order_items, using IN.", "List product_id from order_items.", "SELECT name FROM products WHERE id IN (SELECT product_id FROM order_items);", [["SELECT name FROM products WHERE id NOT IN (SELECT product_id FROM order_items);", "Finds unsold products"], ["SELECT name FROM products;", "Shows every product"]], { recalls: [8], alt: "+ INSERT INTO products VALUES (10, 'Vase', 'Home', 5.0, 2.0);" }),
  A("s34-03", "shop", "Using EXISTS", "Show the name of customers who've placed at least one order, using EXISTS.", "The subquery refers to the outer customer.", "SELECT c.name FROM customers c WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id);", [["SELECT c.name FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id);", "Finds those without"], ["SELECT c.name FROM customers c WHERE EXISTS (SELECT 1 FROM orders o);", "Not connected to the customer, so it's always true"]]),
  A("s34-04", "school", "Never enrolled", "Show the name of students with no enrolments, using NOT EXISTS.", "NOT EXISTS is true when the subquery finds nothing.", "SELECT s.name FROM students s WHERE NOT EXISTS (SELECT 1 FROM enrolments e WHERE e.student_id = s.id);", [["SELECT s.name FROM students s WHERE EXISTS (SELECT 1 FROM enrolments e WHERE e.student_id = s.id);", "Finds enrolled students"], ["SELECT s.name FROM students s WHERE NOT EXISTS (SELECT 1 FROM enrolments e);", "Not connected to the student"]], { recalls: [28] }),
  A("s34-05", "staff", "The NOT IN trap", "Show the name of employees who don't manage anyone. manager_id contains NULLs, which would make a plain NOT IN return nothing.", "Filter NULLs inside the subquery.", "SELECT name FROM employees WHERE id NOT IN (SELECT manager_id FROM employees WHERE manager_id IS NOT NULL);", [["SELECT name FROM employees WHERE id NOT IN (SELECT manager_id FROM employees);", "A NULL in the list makes every row unknown"], ["SELECT name FROM employees WHERE id IN (SELECT manager_id FROM employees WHERE manager_id IS NOT NULL);", "Finds the managers"]], { recalls: [9] }),
  A("s34-06", "staff", "Fix the empty result", "This should find employees with no valid manager, but returns too little. Show their names. Fix it: an employee has no valid manager when manager_id isn't any employee's id, and NULL counts as none.", "Handle NULL explicitly.", "SELECT name FROM employees WHERE manager_id IS NULL OR manager_id NOT IN (SELECT id FROM employees);", [["SELECT name FROM employees WHERE manager_id NOT IN (SELECT id FROM employees);", "Skips NULL manager_id"], ["SELECT name FROM employees WHERE manager_id IS NULL;", "Misses departed managers"]], { starter: "SELECT name\nFROM employees\nWHERE manager_id NOT IN (SELECT id FROM employees);", recalls: [9] }),
  A("s34-07", "shop", "Bought a kitchen product", "Show the name of customers who've bought any Kitchen product.", "Nest subqueries, or join inside one.", "SELECT name FROM customers WHERE id IN (SELECT o.customer_id FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id WHERE p.category = 'Kitchen');", [["SELECT name FROM customers WHERE id IN (SELECT o.customer_id FROM orders o);", "Ignores the category"], ["SELECT name FROM customers WHERE id NOT IN (SELECT o.customer_id FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id WHERE p.category = 'Kitchen');", "Finds those who haven't"]], { recalls: [8], alt: "+ UPDATE products SET category = 'Home' WHERE id = 8;" }),
  A("s34-08", "shop", "Never shipped to", "Show the name of customers with no shipped order, using NOT EXISTS. Customers with no orders count too.", "Add the status inside the subquery.", "SELECT c.name FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id AND o.status = 'shipped');", [["SELECT c.name FROM customers c WHERE NOT EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id);", "Finds only customers with no orders"], ["SELECT c.name FROM customers c WHERE EXISTS (SELECT 1 FROM orders o WHERE o.customer_id = c.id AND o.status <> 'shipped');", "Keeps some with shipped orders"]], { recalls: [28] }),

  A("s35-01", "shop", "Filter a total", "Using a subquery in FROM, show the order_id and units of orders with more than 3 total units. Replace the ___.", "The outer query can use the inner query's columns.", "SELECT order_id, units FROM (SELECT order_id, SUM(quantity) AS units FROM order_items GROUP BY order_id) WHERE units > 3;", [["SELECT order_id, units FROM (SELECT order_id, SUM(quantity) AS units FROM order_items GROUP BY order_id);", "Doesn't filter"], ["SELECT order_id, quantity AS units FROM order_items WHERE quantity > 3;", "Checks single rows"]], { starter: "SELECT order_id, units\nFROM (___)\nWHERE units > 3;", recalls: [20] }),
  A("s35-02", "staff", "Average of averages", "Show the average of each department's average salary, rounded to 2 decimals, as avg_of_avgs. Ignore employees with no department.", "Average inside, average again outside.", "SELECT ROUND(AVG(avg_salary), 2) AS avg_of_avgs FROM (SELECT AVG(salary) AS avg_salary FROM employees WHERE department_id IS NOT NULL GROUP BY department_id);", [["SELECT ROUND(AVG(salary), 2) AS avg_of_avgs FROM employees WHERE department_id IS NOT NULL;", "Averages employees, not departments"], ["SELECT ROUND(AVG(avg_salary), 2) AS avg_of_avgs FROM (SELECT AVG(salary) AS avg_salary FROM employees GROUP BY department_id);", "Includes the NULL group"]], { recalls: [20] }),
  A("s35-03", "shop", "Biggest customer", "Show the customer_id with the most orders and that count as orders. Break ties with the lowest customer_id.", "Sort the grouped result.", "SELECT customer_id, orders FROM (SELECT customer_id, COUNT(*) AS orders FROM orders GROUP BY customer_id) ORDER BY orders DESC, customer_id LIMIT 1;", [["SELECT customer_id, orders FROM (SELECT customer_id, COUNT(*) AS orders FROM orders GROUP BY customer_id) ORDER BY orders, customer_id LIMIT 1;", "Finds the fewest"], ["SELECT customer_id, COUNT(*) AS orders FROM orders;", "Doesn't group"]], { recalls: [21] }),
  A("s35-04", "school", "Joined summary", "Show each student's name and average grade as average, rounded to 1 decimal, by joining students to a subquery of averages.", "Join on the subquery's student_id.", "SELECT s.name, a.average FROM students s JOIN (SELECT student_id, ROUND(AVG(grade), 1) AS average FROM enrolments GROUP BY student_id) a ON a.student_id = s.id;", [["SELECT s.name, a.average FROM students s JOIN (SELECT student_id, ROUND(AVG(grade), 1) AS average FROM enrolments GROUP BY student_id) a ON a.student_id = s.year_group;", "Joins on the wrong column"], ["SELECT s.name, ROUND(MAX(e.grade), 1) AS average FROM students s JOIN enrolments e ON e.student_id = s.id GROUP BY s.id, s.name;", "Uses the highest grade"]], { recalls: [20] }),
  A("s35-05", "shop", "Empty intermediate result", "Show how many orders have more than 100 units as big_orders. There are none in the sample, so the answer should be 0.", "COUNT over an empty subquery is 0.", "SELECT COUNT(*) AS big_orders FROM (SELECT order_id FROM order_items GROUP BY order_id HAVING SUM(quantity) > 100);", [["SELECT order_id AS big_orders FROM order_items GROUP BY order_id HAVING SUM(quantity) > 100;", "Returns no rows"], ["SELECT COUNT(*) AS big_orders FROM order_items;", "Counts every row"]], { recalls: [21], alt: "+ UPDATE order_items SET quantity = 150 WHERE order_id = 12;" }),
  A("s35-06", "shop", "Fix the nested total", "This should show the largest single order's units as most_units, but SQLite can't nest aggregates. Use a subquery in FROM. Fix it.", "Total per order inside, then MAX outside.", "SELECT MAX(units) AS most_units FROM (SELECT SUM(quantity) AS units FROM order_items GROUP BY order_id);", [["SELECT MAX(quantity) AS most_units FROM order_items;", "Finds the largest row"], ["SELECT SUM(quantity) AS most_units FROM order_items;", "Adds everything"]], { starter: "SELECT MAX(SUM(quantity)) AS most_units\nFROM order_items\nGROUP BY order_id;" }),
  A("s35-07", "app", "Days per user", "Show how many users had sessions on at least 2 different days, as regulars.", "Group first, then count the groups.", "SELECT COUNT(*) AS regulars FROM (SELECT user_id FROM sessions GROUP BY user_id HAVING COUNT(DISTINCT session_date) >= 2);", [["SELECT COUNT(*) AS regulars FROM (SELECT user_id FROM sessions GROUP BY user_id HAVING COUNT(*) >= 2);", "Two sessions could be on one day"], ["SELECT COUNT(DISTINCT user_id) AS regulars FROM sessions;", "Counts every active user"]], { recalls: [21] }),
  A("s35-08", "shop", "Share of pending", "Show each customer_id and their percentage of pending orders as pending_pct, rounded to 1 decimal, for customers above 0%, highest first.", "Calculate inside, filter outside.", "SELECT customer_id, pending_pct FROM (SELECT customer_id, ROUND(SUM(CASE WHEN status = 'pending' THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 1) AS pending_pct FROM orders GROUP BY customer_id) WHERE pending_pct > 0 ORDER BY pending_pct DESC;", [["SELECT customer_id, ROUND(SUM(CASE WHEN status = 'pending' THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 1) AS pending_pct FROM orders GROUP BY customer_id ORDER BY pending_pct DESC;", "Doesn't filter"], ["SELECT customer_id, pending_pct FROM (SELECT customer_id, ROUND(SUM(CASE WHEN status = 'pending' THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 1) AS pending_pct FROM orders GROUP BY customer_id) WHERE pending_pct > 0 ORDER BY pending_pct;", "Sorts lowest first"]], { recalls: [22], alt: "+ INSERT INTO orders VALUES (14, 7, '2024-04-01', 'pending'), (15, 9, '2024-04-02', 'pending');" }),

  A("s36-01", "staff", "Above their department", "Show the name of employees earning more than their own department's average. Replace the ___.", "Link the inner query with x.department_id = e.department_id.", "SELECT e.name FROM employees e WHERE e.salary > (SELECT AVG(x.salary) FROM employees x WHERE x.department_id = e.department_id);", [["SELECT e.name FROM employees e WHERE e.salary > (SELECT AVG(x.salary) FROM employees x);", "Uses the company average"], ["SELECT e.name FROM employees e WHERE e.salary < (SELECT AVG(x.salary) FROM employees x WHERE x.department_id = e.department_id);", "Finds those below"]], { starter: "SELECT e.name\nFROM employees e\nWHERE e.salary > (SELECT AVG(x.salary) FROM employees x WHERE ___);", recalls: [19] }),
  A("s36-02", "shop", "Top price per category", "Show the name and price of the most expensive product in each category.", "Compare with MAX within the same category.", "SELECT p.name, p.price FROM products p WHERE p.price = (SELECT MAX(x.price) FROM products x WHERE x.category = p.category);", [["SELECT p.name, p.price FROM products p WHERE p.price = (SELECT MAX(x.price) FROM products x);", "Finds only the overall top"], ["SELECT p.name, p.price FROM products p WHERE p.price = (SELECT MIN(x.price) FROM products x WHERE x.category = p.category);", "Finds the cheapest"]], { recalls: [19] }),
  A("s36-03", "shop", "Latest order per customer", "Show each customer_id and order_date for that customer's most recent order.", "Compare each order with that customer's MAX date.", "SELECT o.customer_id, o.order_date FROM orders o WHERE o.order_date = (SELECT MAX(x.order_date) FROM orders x WHERE x.customer_id = o.customer_id);", [["SELECT o.customer_id, o.order_date FROM orders o WHERE o.order_date = (SELECT MAX(x.order_date) FROM orders x);", "Finds only the overall latest"], ["SELECT o.customer_id, o.order_date FROM orders o WHERE o.order_date = (SELECT MIN(x.order_date) FROM orders x WHERE x.customer_id = o.customer_id);", "Finds the first order"]], { recalls: [19] }),
  A("s36-04", "school", "Best in course", "Show the student_id and grade of the top grade in each course, including ties.", "Compare each grade with the course's MAX.", "SELECT e.student_id, e.grade FROM enrolments e WHERE e.grade = (SELECT MAX(x.grade) FROM enrolments x WHERE x.course_id = e.course_id);", [["SELECT e.student_id, e.grade FROM enrolments e WHERE e.grade = (SELECT MAX(x.grade) FROM enrolments x);", "Finds only the overall top"], ["SELECT student_id, MAX(grade) AS grade FROM enrolments GROUP BY student_id;", "Finds each student's top"]], { recalls: [19] }),
  A("s36-05", "weather", "The first reading", "Show the city and temp_c of each city's earliest reading.", "Compare the date with that city's MIN date.", "SELECT r.city, r.temp_c FROM readings r WHERE r.reading_date = (SELECT MIN(x.reading_date) FROM readings x WHERE x.city = r.city);", [["SELECT r.city, r.temp_c FROM readings r WHERE r.reading_date = (SELECT MIN(x.reading_date) FROM readings x);", "Uses one date for every city"], ["SELECT r.city, MIN(r.temp_c) AS temp_c FROM readings r GROUP BY r.city;", "Finds the lowest temperature"]], { recalls: [6], alt: "+ UPDATE readings SET reading_date = '2024-07-29' WHERE id = 14;" }),
  A("s36-06", "staff", "Fix the link", "This should show employees earning the top salary in their own department, but it isn't linked to the outer row, so it finds only one. Fix it.", "Add the department condition inside.", "SELECT e.name FROM employees e WHERE e.salary = (SELECT MAX(x.salary) FROM employees x WHERE x.department_id = e.department_id);", [["SELECT e.name FROM employees e WHERE e.salary = (SELECT MAX(x.salary) FROM employees x);", "Still isn't linked"], ["SELECT e.name FROM employees e WHERE e.salary = (SELECT MIN(x.salary) FROM employees x WHERE x.department_id = e.department_id);", "Finds the lowest"]], { starter: "SELECT e.name\nFROM employees e\nWHERE e.salary = (SELECT MAX(x.salary) FROM employees x);", recalls: [6] }),
  A("s36-07", "staff", "Earlier hire exists", "Show the name of employees for whom someone in the same department was hired earlier.", "EXISTS with two linking conditions.", "SELECT e.name FROM employees e WHERE EXISTS (SELECT 1 FROM employees x WHERE x.department_id = e.department_id AND x.hire_date < e.hire_date);", [["SELECT e.name FROM employees e WHERE EXISTS (SELECT 1 FROM employees x WHERE x.hire_date < e.hire_date);", "Compares across departments"], ["SELECT e.name FROM employees e WHERE NOT EXISTS (SELECT 1 FROM employees x WHERE x.department_id = e.department_id AND x.hire_date < e.hire_date);", "Finds the earliest in each"]], { recalls: [30] }),
  A("s36-08", "shop", "Above-average orders per customer", "Show the customer_id and order id as order_id of orders with more units than that customer's average order.", "Compute order totals with a subquery, used on both sides.", "SELECT t.customer_id, t.order_id FROM (SELECT o.customer_id, i.order_id, SUM(i.quantity) AS units FROM orders o JOIN order_items i ON i.order_id = o.id GROUP BY o.customer_id, i.order_id) t WHERE t.units > (SELECT AVG(y.units) FROM (SELECT o.customer_id, i.order_id, SUM(i.quantity) AS units FROM orders o JOIN order_items i ON i.order_id = o.id GROUP BY o.customer_id, i.order_id) y WHERE y.customer_id = t.customer_id);", [["SELECT t.customer_id, t.order_id FROM (SELECT o.customer_id, i.order_id, SUM(i.quantity) AS units FROM orders o JOIN order_items i ON i.order_id = o.id GROUP BY o.customer_id, i.order_id) t;", "Doesn't filter"], ["SELECT t.customer_id, t.order_id FROM (SELECT o.customer_id, i.order_id, SUM(i.quantity) AS units FROM orders o JOIN order_items i ON i.order_id = o.id GROUP BY o.customer_id, i.order_id) t WHERE t.units > (SELECT AVG(quantity) FROM order_items);", "Uses the overall average"]], { recalls: [19] }),

  A("s37-01", "staff", "Name a step", "Using a CTE named dept_totals, total salaries per department_id as total, then show rows with a total above 100000. Replace the ___.", "The main query reads the CTE like a table.", "WITH dept_totals AS (SELECT department_id, SUM(salary) AS total FROM employees GROUP BY department_id) SELECT department_id, total FROM dept_totals WHERE total > 100000;", [["WITH dept_totals AS (SELECT department_id, SUM(salary) AS total FROM employees GROUP BY department_id) SELECT department_id, total FROM dept_totals;", "Doesn't filter"], ["WITH dept_totals AS (SELECT department_id, MAX(salary) AS total FROM employees GROUP BY department_id) SELECT department_id, total FROM dept_totals WHERE total > 100000;", "Uses the top salary"]], { starter: "WITH dept_totals AS (\n  SELECT department_id, SUM(salary) AS total\n  FROM employees\n  GROUP BY department_id\n)\nSELECT department_id, total\nFROM ___\nWHERE total > 100000;", recalls: [20] }),
  A("s37-02", "shop", "Join a CTE", "With a CTE of units per order, show each customer_id and total units as units.", "Join the CTE to orders.", "WITH t AS (SELECT order_id, SUM(quantity) AS units FROM order_items GROUP BY order_id) SELECT o.customer_id, SUM(t.units) AS units FROM orders o JOIN t ON t.order_id = o.id GROUP BY o.customer_id;", [["WITH t AS (SELECT order_id, COUNT(*) AS units FROM order_items GROUP BY order_id) SELECT o.customer_id, SUM(t.units) AS units FROM orders o JOIN t ON t.order_id = o.id GROUP BY o.customer_id;", "Counts rows, not units"], ["SELECT customer_id, COUNT(*) AS units FROM orders GROUP BY customer_id;", "Counts orders"]], { recalls: [25, 29] }),
  A("s37-03", "staff", "Two steps", "Use two CTEs: dept_avg for each department's average salary, and overall for the average of all salaries. Show the department_id of departments averaging above the overall average.", "Separate CTEs with a comma.", "WITH dept_avg AS (SELECT department_id, AVG(salary) AS average FROM employees WHERE department_id IS NOT NULL GROUP BY department_id), overall AS (SELECT AVG(salary) AS average FROM employees) SELECT d.department_id FROM dept_avg d, overall o WHERE d.average > o.average;", [["WITH dept_avg AS (SELECT department_id, AVG(salary) AS average FROM employees WHERE department_id IS NOT NULL GROUP BY department_id) SELECT department_id FROM dept_avg;", "Doesn't compare with the overall average"], ["WITH dept_avg AS (SELECT department_id, AVG(salary) AS average FROM employees WHERE department_id IS NOT NULL GROUP BY department_id), overall AS (SELECT AVG(salary) AS average FROM employees) SELECT d.department_id FROM dept_avg d, overall o WHERE d.average < o.average;", "Finds those below"]], { recalls: [35] }),
  A("s37-04", "school", "Passing students", "With a CTE of each student's average grade, show the name of students averaging at least 70.", "Join the CTE to students.", "WITH a AS (SELECT student_id, AVG(grade) AS average FROM enrolments GROUP BY student_id) SELECT s.name FROM students s JOIN a ON a.student_id = s.id WHERE a.average >= 70;", [["WITH a AS (SELECT student_id, AVG(grade) AS average FROM enrolments GROUP BY student_id) SELECT s.name FROM students s JOIN a ON a.student_id = s.id WHERE a.average > 70;", "Leaves out exactly 70"], ["SELECT s.name FROM students s JOIN enrolments e ON e.student_id = s.id WHERE e.grade >= 70;", "Checks single grades"]], { recalls: [25], alt: "+ UPDATE enrolments SET grade = 80 WHERE id = 11; UPDATE enrolments SET grade = 60 WHERE id = 12; INSERT INTO enrolments VALUES (15, 8, 5, 69, '2024-spring');" }),
  A("s37-05", "shop", "Empty step", "With a CTE of cancelled orders, show how many of them each customer_id has as cancelled, only for customers appearing in it. Customers with none don't appear.", "A CTE can be small, or empty.", "WITH c AS (SELECT customer_id FROM orders WHERE status = 'cancelled') SELECT customer_id, COUNT(*) AS cancelled FROM c GROUP BY customer_id;", [["SELECT customer_id, COUNT(*) AS cancelled FROM orders GROUP BY customer_id;", "Counts every status"], ["WITH c AS (SELECT customer_id FROM orders WHERE status = 'shipped') SELECT customer_id, COUNT(*) AS cancelled FROM c GROUP BY customer_id;", "Uses the wrong status"]], { recalls: [20] }),
  A("s37-06", "staff", "Fix the WITH", "This should use a CTE named top to find the highest salary, then show who earns it, but it fails. Fix it.", "Every WITH needs AS and brackets.", "WITH top AS (SELECT MAX(salary) AS salary FROM employees) SELECT e.name FROM employees e JOIN top ON top.salary = e.salary;", [["SELECT name FROM employees;", "Shows everyone"], ["WITH top AS (SELECT MIN(salary) AS salary FROM employees) SELECT e.name FROM employees e JOIN top ON top.salary = e.salary;", "Finds the lowest"]], { starter: "WITH top SELECT MAX(salary) AS salary FROM employees\nSELECT e.name\nFROM employees e\nJOIN top ON top.salary = e.salary;" }),
  A("s37-07", "shop", "Step by step revenue", "Use a CTE to calculate line revenue (price times quantity) per order_id as revenue, then show the average order revenue as avg_revenue, rounded to 2 decimals.", "Total per order, then average.", "WITH r AS (SELECT i.order_id, SUM(p.price * i.quantity) AS revenue FROM order_items i JOIN products p ON p.id = i.product_id GROUP BY i.order_id) SELECT ROUND(AVG(revenue), 2) AS avg_revenue FROM r;", [["SELECT ROUND(AVG(p.price * i.quantity), 2) AS avg_revenue FROM order_items i JOIN products p ON p.id = i.product_id;", "Averages lines, not orders"], ["WITH r AS (SELECT i.order_id, SUM(p.price) AS revenue FROM order_items i JOIN products p ON p.id = i.product_id GROUP BY i.order_id) SELECT ROUND(AVG(revenue), 2) AS avg_revenue FROM r;", "Ignores quantity"]], { recalls: [25, 35] }),
  A("s37-08", "school", "Course leaderboard", "Using CTEs, find each course_id's average grade and the highest such average. Show the title of each course matching the highest average.", "One CTE for averages, then compare with MAX.", "WITH a AS (SELECT course_id, AVG(grade) AS average FROM enrolments GROUP BY course_id) SELECT c.title FROM a JOIN courses c ON c.id = a.course_id WHERE a.average = (SELECT MAX(average) FROM a);", [["WITH a AS (SELECT course_id, AVG(grade) AS average FROM enrolments GROUP BY course_id) SELECT c.title FROM a JOIN courses c ON c.id = a.course_id;", "Shows every course"], ["WITH a AS (SELECT course_id, AVG(grade) AS average FROM enrolments GROUP BY course_id) SELECT c.title FROM a JOIN courses c ON c.id = a.course_id WHERE a.average = (SELECT MIN(average) FROM a);", "Finds the lowest"]], { recalls: [20, 32] }),

  A("s38-01", "shop", "Stack two lists", "Show one list of names: customer names followed by product names. Keep any duplicates, using UNION ALL. Replace the ___.", "Both queries must have one column.", "SELECT name FROM customers UNION ALL SELECT name FROM products;", [["SELECT name FROM customers;", "Leaves out products"], ["SELECT name FROM customers UNION ALL SELECT category FROM products;", "Uses the wrong column"]], { starter: "SELECT name FROM customers\n___\nSELECT name FROM products;" }),
  A("s38-02", "shop", "Remove duplicates", "Show every different city and category in a single column named value, removing duplicates, using UNION.", "UNION removes duplicates automatically.", "SELECT city AS value FROM customers UNION SELECT category FROM products;", [["SELECT city AS value FROM customers UNION ALL SELECT category FROM products;", "Keeps duplicates"], ["SELECT city AS value FROM customers;", "Leaves out categories"]], { recalls: [10] }),
  A("s38-03", "shop", "Label the rows", "Show each name with a column kind: Customer for customers and Product for products. Sort by kind, then name.", "Add a fixed text column to each branch.", "SELECT name, 'Customer' AS kind FROM customers UNION ALL SELECT name, 'Product' FROM products ORDER BY kind, name;", [["SELECT name, 'Customer' AS kind FROM customers UNION ALL SELECT name, 'Customer' FROM products ORDER BY kind, name;", "Mislabels products"], ["SELECT name, 'Customer' AS kind FROM customers UNION ALL SELECT name, 'Product' FROM products ORDER BY name;", "Doesn't sort by kind"]], { recalls: [11] }),
  A("s38-04", "app", "Both sides count", "Show one column, user_id, listing every id found in either users.id or users.referrer_id. Remove NULLs and duplicates.", "UNION removes duplicates, and filter NULLs.", "SELECT id AS user_id FROM users UNION SELECT referrer_id FROM users WHERE referrer_id IS NOT NULL;", [["SELECT id AS user_id FROM users UNION ALL SELECT referrer_id FROM users WHERE referrer_id IS NOT NULL;", "Keeps duplicates"], ["SELECT id AS user_id FROM users UNION SELECT referrer_id FROM users;", "Keeps NULL"]], { recalls: [10] }),
  A("s38-05", "staff", "Fixed categories", "Using UNION ALL, show exactly three rows in a column named band: Low, Mid, and High. Beside each, show as staff how many employees earn under 50000, from 50000 to 90000, and over 90000.", "Each branch counts its own band.", "SELECT 'Low' AS band, COUNT(*) AS staff FROM employees WHERE salary < 50000 UNION ALL SELECT 'Mid', COUNT(*) FROM employees WHERE salary BETWEEN 50000 AND 90000 UNION ALL SELECT 'High', COUNT(*) FROM employees WHERE salary > 90000;", [["SELECT CASE WHEN salary < 50000 THEN 'Low' WHEN salary <= 90000 THEN 'Mid' ELSE 'High' END AS band, COUNT(*) AS staff FROM employees GROUP BY band;", "An empty band disappears"], ["SELECT 'Low' AS band, COUNT(*) AS staff FROM employees WHERE salary < 50000 UNION ALL SELECT 'Mid', COUNT(*) FROM employees WHERE salary > 50000 AND salary < 90000 UNION ALL SELECT 'High', COUNT(*) FROM employees WHERE salary > 90000;", "Misses the exact limits"]], { recalls: [17], alt: "+ UPDATE employees SET salary = 80000 WHERE id = 11; UPDATE employees SET salary = 90000 WHERE id = 12;" }),
  A("s38-06", "shop", "Fix the branches", "This should list customer names and then product names, with a label, but the branches have different column counts. Fix it so both have name and kind.", "Each branch needs the same number of columns.", "SELECT name, 'C' AS kind FROM customers UNION ALL SELECT name, 'P' FROM products;", [["SELECT name FROM customers UNION ALL SELECT name FROM products;", "Removes the label"], ["SELECT name, 'C' AS kind FROM customers;", "Leaves out products"]], { starter: "SELECT name, 'C' AS kind FROM customers\nUNION ALL\nSELECT name FROM products;" }),
  A("s38-07", "app", "Sorted branches", "Show the single longest session's minutes and the single shortest session's minutes, as two rows, longest first, in a column named minutes.", "Wrap each sorted branch in a FROM subquery, as SQLite has no brackets around branches.", "SELECT minutes FROM (SELECT minutes FROM sessions ORDER BY minutes DESC LIMIT 1) UNION ALL SELECT minutes FROM (SELECT minutes FROM sessions ORDER BY minutes LIMIT 1);", [["SELECT MAX(minutes) AS minutes FROM sessions;", "Leaves out the shortest"], ["SELECT minutes FROM (SELECT minutes FROM sessions ORDER BY minutes LIMIT 1) UNION ALL SELECT minutes FROM (SELECT minutes FROM sessions ORDER BY minutes DESC LIMIT 1);", "Puts the shortest first"]], { recalls: [11], ordered: true }),
  A("s38-08", "school", "Combined totals", "Show each student_id and the number of graded enrolments plus the number of ungraded enrolments, as a stacked list with kind (Graded or Pending) and total. Skip zeros.", "Each branch filters and groups.", "SELECT student_id, 'Graded' AS kind, COUNT(*) AS total FROM enrolments WHERE grade IS NOT NULL GROUP BY student_id UNION ALL SELECT student_id, 'Pending', COUNT(*) FROM enrolments WHERE grade IS NULL GROUP BY student_id;", [["SELECT student_id, 'Graded' AS kind, COUNT(*) AS total FROM enrolments GROUP BY student_id;", "Mixes both kinds"], ["SELECT student_id, 'Graded' AS kind, COUNT(*) AS total FROM enrolments WHERE grade IS NOT NULL GROUP BY student_id;", "Leaves out Pending"]], { recalls: [17] }),

  A("s39-01", "shop", "In both", "Show the customer ids that appear in both customers and orders, using INTERSECT. Replace the ___.", "INTERSECT keeps rows found in both.", "SELECT id FROM customers INTERSECT SELECT customer_id FROM orders;", [["SELECT id FROM customers EXCEPT SELECT customer_id FROM orders;", "Keeps those in only the first"], ["SELECT id FROM customers UNION SELECT customer_id FROM orders;", "Keeps everything"]], { starter: "SELECT id FROM customers\n___\nSELECT customer_id FROM orders;" }),
  A("s39-02", "shop", "Only in the first", "Show customer ids that have never placed an order, using EXCEPT.", "EXCEPT removes rows found in the second result.", "SELECT id FROM customers EXCEPT SELECT customer_id FROM orders;", [["SELECT id FROM customers INTERSECT SELECT customer_id FROM orders;", "Keeps those in both"], ["SELECT customer_id FROM orders EXCEPT SELECT id FROM customers;", "Reverses the direction"]], { recalls: [28] }),
  A("s39-03", "shop", "Order matters", "Show product ids that sold but aren't in the products table, using EXCEPT. Usually there are none, but check anyway.", "Start from the sold list.", "SELECT product_id FROM order_items EXCEPT SELECT id FROM products;", [["SELECT id FROM products EXCEPT SELECT product_id FROM order_items;", "Finds unsold products"], ["SELECT product_id FROM order_items INTERSECT SELECT id FROM products;", "Finds valid sales"]], { recalls: [38], alt: "+ INSERT INTO order_items VALUES (11, 99, 1, NULL);" }),
  A("s39-04", "school", "Taken Maths and Science", "Show student_ids who've enrolled in course 1 and also in course 3, using INTERSECT.", "One branch per course.", "SELECT student_id FROM enrolments WHERE course_id = 1 INTERSECT SELECT student_id FROM enrolments WHERE course_id = 3;", [["SELECT student_id FROM enrolments WHERE course_id = 1 UNION SELECT student_id FROM enrolments WHERE course_id = 3;", "Accepts either course"], ["SELECT student_id FROM enrolments WHERE course_id = 1 AND course_id = 3;", "One row can't be both"]], { recalls: [38], alt: "+ UPDATE enrolments SET course_id = 1 WHERE id = 11; UPDATE enrolments SET course_id = 3 WHERE id = 12;" }),
  A("s39-05", "staff", "NULLs and sets", "Show the different manager_id values that aren't an employee id, using EXCEPT. NULL appears as one row, because EXCEPT treats NULLs as equal.", "List manager_id first.", "SELECT manager_id FROM employees EXCEPT SELECT id FROM employees;", [["SELECT id FROM employees EXCEPT SELECT manager_id FROM employees;", "Reverses the direction"], ["SELECT manager_id FROM employees WHERE manager_id NOT IN (SELECT id FROM employees);", "Drops NULL"]], { recalls: [10] }),
  A("s39-06", "shop", "Fix the columns", "This should find customer ids with no order, but the branches have different column counts. Fix it.", "Each branch needs one column.", "SELECT id FROM customers EXCEPT SELECT customer_id FROM orders;", [["SELECT id FROM customers;", "Doesn't remove anyone"], ["SELECT id FROM customers INTERSECT SELECT customer_id FROM orders;", "Keeps those with orders"]], { starter: "SELECT id FROM customers\nEXCEPT\nSELECT customer_id, id FROM orders;" }),
  A("s39-07", "app", "Web but not iOS", "Show the user_id of users who've used web but never ios.", "EXCEPT with two filtered branches.", "SELECT user_id FROM sessions WHERE device = 'web' EXCEPT SELECT user_id FROM sessions WHERE device = 'ios';", [["SELECT user_id FROM sessions WHERE device = 'web' INTERSECT SELECT user_id FROM sessions WHERE device = 'ios';", "Finds users of both"], ["SELECT user_id FROM sessions WHERE device = 'web';", "Doesn't remove iOS users"]], { recalls: [38], alt: "+ INSERT INTO sessions VALUES (15, 8, '2024-03-03', 9, 'web');" }),
  A("s39-08", "shop", "Bought Kitchen, never Home", "Show the name of customers who bought a Kitchen product but never a Home product.", "Use EXCEPT in a subquery, then look up names.", "SELECT name FROM customers WHERE id IN (SELECT o.customer_id FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id WHERE p.category = 'Kitchen' EXCEPT SELECT o.customer_id FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id WHERE p.category = 'Home');", [["SELECT name FROM customers WHERE id IN (SELECT o.customer_id FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id WHERE p.category = 'Kitchen');", "Doesn't remove Home buyers"], ["SELECT name FROM customers WHERE id IN (SELECT o.customer_id FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id WHERE p.category = 'Home');", "Finds Home buyers"]], { recalls: [28], alt: "+ UPDATE order_items SET product_id = 7 WHERE order_id = 12;" }),

  A("st06-r01", "staff", "Below the average", "Show the name of employees earning below the overall average, A to Z.", "Calculate one value, then compare.", "SELECT name FROM employees WHERE salary < (SELECT AVG(salary) FROM employees) ORDER BY name;", [["SELECT name FROM employees WHERE salary > (SELECT AVG(salary) FROM employees) ORDER BY name;", "Finds those above"], ["SELECT name FROM employees ORDER BY name;", "Doesn't filter"]], { skills: [33, 11] }),
  A("st06-r02", "shop", "Customers without a Kitchen buy", "Show the name of customers who've never bought a Kitchen product.", "Careful with customers who have no orders.", "SELECT name FROM customers WHERE id NOT IN (SELECT o.customer_id FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id WHERE p.category = 'Kitchen');", [["SELECT name FROM customers WHERE id IN (SELECT o.customer_id FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id WHERE p.category = 'Kitchen');", "Finds buyers"], ["SELECT name FROM customers;", "Keeps everyone"]], { skills: [34] }),
  A("st06-r03", "school", "Course average spread", "Show the highest course average minus the lowest course average, rounded to 1 decimal, as spread.", "Aggregate the aggregates.", "SELECT ROUND(MAX(average) - MIN(average), 1) AS spread FROM (SELECT AVG(grade) AS average FROM enrolments GROUP BY course_id);", [["SELECT ROUND(MAX(grade) - MIN(grade), 1) AS spread FROM enrolments;", "Compares single grades"], ["SELECT ROUND(MAX(average), 1) AS spread FROM (SELECT AVG(grade) AS average FROM enrolments GROUP BY course_id);", "Doesn't subtract"]], { skills: [35] }),
  A("st06-r04", "weather", "Hottest in its city", "Show the id of each city's hottest reading, including ties.", "Compare each reading with its own city.", "SELECT r.id FROM readings r WHERE r.temp_c = (SELECT MAX(x.temp_c) FROM readings x WHERE x.city = r.city);", [["SELECT r.id FROM readings r WHERE r.temp_c = (SELECT MAX(x.temp_c) FROM readings x);", "Finds only the overall hottest"], ["SELECT city, MAX(id) AS id FROM readings GROUP BY city;", "Finds the latest id"]], { skills: [36] }),
  A("st06-r05", "shop", "Spend ranking", "Using a CTE of revenue per customer_id (price times quantity), show the id and name of the top-spending customer.", "Name the step, join, sort, and limit.", "WITH r AS (SELECT o.customer_id, SUM(p.price * i.quantity) AS revenue FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id GROUP BY o.customer_id) SELECT c.id, c.name FROM r JOIN customers c ON c.id = r.customer_id ORDER BY r.revenue DESC LIMIT 1;", [["WITH r AS (SELECT o.customer_id, SUM(p.price * i.quantity) AS revenue FROM orders o JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id GROUP BY o.customer_id) SELECT c.id, c.name FROM r JOIN customers c ON c.id = r.customer_id ORDER BY r.revenue LIMIT 1;", "Finds the lowest"], ["SELECT c.id, c.name FROM customers c LIMIT 1;", "Doesn't calculate"]], { skills: [37, 25] }),
  A("st06-r06", "contacts", "All contact points", "Show every known email and phone in one column named contact, removing duplicates.", "Stack two columns, and skip NULLs.", "SELECT email AS contact FROM contacts WHERE email IS NOT NULL UNION SELECT phone FROM contacts WHERE phone IS NOT NULL;", [["SELECT email AS contact FROM contacts UNION SELECT phone FROM contacts;", "Keeps NULL"], ["SELECT email AS contact FROM contacts WHERE email IS NOT NULL;", "Leaves out phones"]], { skills: [38, 9] }),
  A("st06-r07", "school", "Enrolled but ungraded", "Show the student_ids with an enrolment but never a grade, using a set operation.", "Students with any grade get removed.", "SELECT student_id FROM enrolments EXCEPT SELECT student_id FROM enrolments WHERE grade IS NOT NULL;", [["SELECT student_id FROM enrolments WHERE grade IS NULL;", "Keeps students with other grades"], ["SELECT student_id FROM enrolments INTERSECT SELECT student_id FROM enrolments WHERE grade IS NOT NULL;", "Finds those with grades"]], { skills: [39, 9], alt: "+ INSERT INTO enrolments VALUES (15, 8, 6, NULL, '2024-spring');" }),
  A("st06-r08", "app", "Above-average users", "Show the username of users whose total minutes exceed the average per-user total.", "Compare a total with an average of totals.", "WITH t AS (SELECT user_id, SUM(minutes) AS total FROM sessions GROUP BY user_id) SELECT u.username FROM users u JOIN t ON t.user_id = u.id WHERE t.total > (SELECT AVG(total) FROM t);", [["WITH t AS (SELECT user_id, SUM(minutes) AS total FROM sessions GROUP BY user_id) SELECT u.username FROM users u JOIN t ON t.user_id = u.id;", "Doesn't compare"], ["SELECT u.username FROM users u JOIN sessions s ON s.user_id = u.id WHERE s.minutes > (SELECT AVG(minutes) FROM sessions);", "Compares single sessions"]], { skills: [35, 37] }),
  A("st06-r09", "shop", "Unsold share", "Show the percentage of products never sold, rounded to 1 decimal, as unsold_pct.", "Count with a subquery, divided by all products.", "SELECT ROUND((SELECT COUNT(*) FROM products WHERE id NOT IN (SELECT product_id FROM order_items)) * 100.0 / (SELECT COUNT(*) FROM products), 1) AS unsold_pct;", [["SELECT ROUND((SELECT COUNT(*) FROM products WHERE id IN (SELECT product_id FROM order_items)) * 100.0 / (SELECT COUNT(*) FROM products), 1) AS unsold_pct;", "Finds the sold share"], ["SELECT (SELECT COUNT(*) FROM products WHERE id NOT IN (SELECT product_id FROM order_items)) AS unsold_pct;", "A count isn't a percentage"]], { skills: [33, 34], alt: "+ INSERT INTO products VALUES (10, 'Vase', 'Home', 5.0, 2.0);" }),
  A("st06-r10", "staff", "Newest per department", "Show the department_id and name of the most recent hire in each department. Ignore employees with no department.", "Compare with the department's latest date.", "SELECT e.department_id, e.name FROM employees e WHERE e.hire_date = (SELECT MAX(x.hire_date) FROM employees x WHERE x.department_id = e.department_id);", [["SELECT e.department_id, e.name FROM employees e WHERE e.hire_date = (SELECT MAX(x.hire_date) FROM employees x);", "Finds only the latest overall"], ["SELECT e.department_id, e.name FROM employees e WHERE e.hire_date = (SELECT MIN(x.hire_date) FROM employees x WHERE x.department_id = e.department_id);", "Finds the earliest"]], { skills: [36] }),
  A("st06-r11", "shop", "Two kinds of customer", "Show each customer's name and a segment: Buyer if they appear in orders, otherwise Browser, by stacking two queries.", "Use UNION ALL with IN and NOT IN.", "SELECT name, 'Buyer' AS segment FROM customers WHERE id IN (SELECT customer_id FROM orders) UNION ALL SELECT name, 'Browser' FROM customers WHERE id NOT IN (SELECT customer_id FROM orders);", [["SELECT name, 'Buyer' AS segment FROM customers;", "Labels everyone Buyer"], ["SELECT name, 'Buyer' AS segment FROM customers WHERE id IN (SELECT customer_id FROM orders);", "Leaves out Browser"]], { skills: [34, 38] }),
  A("st06-r12", "school", "Students above their year", "Show the name of students whose average grade is above the average of their year group.", "A correlated subquery over a CTE.", "WITH a AS (SELECT s.id, s.name, s.year_group, AVG(e.grade) AS average FROM students s JOIN enrolments e ON e.student_id = s.id GROUP BY s.id, s.name, s.year_group) SELECT a.name FROM a WHERE a.average > (SELECT AVG(x.average) FROM a x WHERE x.year_group = a.year_group);", [["WITH a AS (SELECT s.id, s.name, s.year_group, AVG(e.grade) AS average FROM students s JOIN enrolments e ON e.student_id = s.id GROUP BY s.id, s.name, s.year_group) SELECT a.name FROM a WHERE a.average > (SELECT AVG(x.average) FROM a x);", "Uses the overall average"], ["SELECT name FROM students;", "Shows everyone"]], { skills: [36, 37], alt: "+ INSERT INTO students VALUES (10, 'Iris', 10); INSERT INTO enrolments VALUES (15, 8, 5, 50, '2024-spring'), (16, 10, 5, 65, '2024-spring');" }),
  A("st06-r13", "app", "Inviters who play", "Show the username of users who've invited someone and also have a session, using INTERSECT on ids and a lookup.", "Intersect in a subquery.", "SELECT username FROM users WHERE id IN (SELECT referrer_id FROM users INTERSECT SELECT user_id FROM sessions);", [["SELECT username FROM users WHERE id IN (SELECT referrer_id FROM users);", "Ignores sessions"], ["SELECT username FROM users WHERE id IN (SELECT user_id FROM sessions);", "Ignores invites"]], { skills: [39, 34], alt: "+ DELETE FROM sessions WHERE user_id = 7; UPDATE users SET referrer_id = 8 WHERE id = 9;" }),
  A("st06-r14", "staff", "Salary gap to the top", "Show each employee's name and how far they are below the highest salary in their department as gap. Ignore employees with no department.", "A correlated subquery in SELECT.", "SELECT e.name, (SELECT MAX(x.salary) FROM employees x WHERE x.department_id = e.department_id) - e.salary AS gap FROM employees e WHERE e.department_id IS NOT NULL;", [["SELECT e.name, (SELECT MAX(x.salary) FROM employees x) - e.salary AS gap FROM employees e WHERE e.department_id IS NOT NULL;", "Uses the company's top salary"], ["SELECT e.name, e.salary AS gap FROM employees e WHERE e.department_id IS NOT NULL;", "Doesn't subtract"]], { skills: [36, 12] }),
  A("st06-r15", "shop", "Biggest order's customer", "Show the name of the customer who placed the order with the most total units. Break ties with the lowest order id.", "Find the order first, then walk to the customer.", "SELECT c.name FROM customers c JOIN orders o ON o.customer_id = c.id WHERE o.id = (SELECT order_id FROM order_items GROUP BY order_id ORDER BY SUM(quantity) DESC, order_id LIMIT 1);", [["SELECT c.name FROM customers c JOIN orders o ON o.customer_id = c.id WHERE o.id = (SELECT order_id FROM order_items ORDER BY quantity DESC LIMIT 1);", "Uses the largest row, not order total"], ["SELECT c.name FROM customers c LIMIT 1;", "Doesn't calculate"]], { skills: [33, 25], alt: "+ INSERT INTO order_items VALUES (12, 8, 3, NULL);" }),

  A("st06-c01:18", "school", "Enrolment rate", "Show each course_id and the percentage of all students enrolled in it, rounded to 2 decimals, as rate. Sort by rate descending, then course_id ascending. A retake counts once.", "The denominator is every student.", "SELECT course_id, ROUND(COUNT(DISTINCT student_id) * 100.0 / (SELECT COUNT(*) FROM students), 2) AS rate FROM enrolments GROUP BY course_id ORDER BY rate DESC, course_id;", [["SELECT course_id, ROUND(COUNT(*) * 100.0 / (SELECT COUNT(*) FROM students), 2) AS rate FROM enrolments GROUP BY course_id ORDER BY rate DESC, course_id;", "Counts retakes twice"], ["SELECT course_id, ROUND(COUNT(DISTINCT student_id) * 100.0 / (SELECT COUNT(DISTINCT student_id) FROM enrolments), 2) AS rate FROM enrolments GROUP BY course_id ORDER BY rate DESC, course_id;", "Excludes students with no enrolments"]], { skills: [33, 18, 11] }),
  A("st06-c02:21", "shop", "Immediate first orders", "An order is same-day if the customer signed up that day. Considering only each customer's first order, show the percentage that were same-day, rounded to 2 decimals, as same_day_pct.", "Find first orders with a subquery.", "SELECT ROUND(SUM(CASE WHEN o.order_date = c.signup_date THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) AS same_day_pct FROM orders o JOIN customers c ON c.id = o.customer_id WHERE o.order_date = (SELECT MIN(x.order_date) FROM orders x WHERE x.customer_id = o.customer_id);", [["SELECT ROUND(SUM(CASE WHEN o.order_date = c.signup_date THEN 1 ELSE 0 END) * 100.0 / COUNT(*), 2) AS same_day_pct FROM orders o JOIN customers c ON c.id = o.customer_id;", "Uses every order"], ["SELECT ROUND(SUM(CASE WHEN o.order_date = c.signup_date THEN 1 ELSE 0 END) / COUNT(*), 2) AS same_day_pct FROM orders o JOIN customers c ON c.id = o.customer_id WHERE o.order_date = (SELECT MIN(x.order_date) FROM orders x WHERE x.customer_id = o.customer_id);", "Integer division, not a percentage"]], { skills: [36, 22], alt: "UPDATE customers SET signup_date = '2024-01-05' WHERE id = 1; UPDATE customers SET signup_date = '2024-01-17' WHERE id = 2; UPDATE orders SET order_date = '2024-01-01' WHERE id = 3;" }),
  A("st06-c03:22", "app", "Came back next day", "Show the fraction of users who had a session on the day after their first session, rounded to 2 decimals, as fraction. The denominator is users with at least one session.", "Find each user's first date, then look for the next day.", "WITH f AS (SELECT user_id, MIN(session_date) AS first_day FROM sessions GROUP BY user_id) SELECT ROUND(SUM(CASE WHEN EXISTS (SELECT 1 FROM sessions s WHERE s.user_id = f.user_id AND s.session_date = date(f.first_day, '+1 day')) THEN 1 ELSE 0 END) * 1.0 / COUNT(*), 2) AS fraction FROM f;", [["SELECT ROUND(COUNT(DISTINCT a.user_id) * 1.0 / (SELECT COUNT(DISTINCT user_id) FROM sessions), 2) AS fraction FROM sessions a JOIN sessions b ON b.user_id = a.user_id AND b.session_date = date(a.session_date, '+1 day');", "Accepts any consecutive days"], ["SELECT COUNT(*) AS fraction FROM sessions;", "Doesn't calculate"]], { skills: [36, 37, 16], alt: "+ UPDATE sessions SET session_date = '2024-03-02' WHERE id = 12;" }),
  A("st06-c04:25", "shop", "First day of sales", "Find each product's first order date, then show product_id, first_date, and quantity for every item sold on that date.", "Keep every row from that first date.", "SELECT i.product_id, o.order_date AS first_date, i.quantity FROM order_items i JOIN orders o ON o.id = i.order_id WHERE o.order_date = (SELECT MIN(x.order_date) FROM order_items y JOIN orders x ON x.id = y.order_id WHERE y.product_id = i.product_id);", [["SELECT i.product_id, MIN(o.order_date) AS first_date, i.quantity FROM order_items i JOIN orders o ON o.id = i.order_id GROUP BY i.product_id;", "Keeps only one row per product"], ["SELECT i.product_id, o.order_date AS first_date, i.quantity FROM order_items i JOIN orders o ON o.id = i.order_id;", "Keeps every date"]], { skills: [36, 25], alt: "+ INSERT INTO order_items VALUES (11, 8, 5, NULL);" }),
  A("st06-c05:28", "app", "The largest unique value", "A session length is unique if only one session has it. Show the largest unique minutes value as minutes. If none exists, return one row containing NULL.", "Keep values seen once, then take MAX.", "SELECT MAX(minutes) AS minutes FROM (SELECT minutes FROM sessions GROUP BY minutes HAVING COUNT(*) = 1);", [["SELECT minutes FROM sessions GROUP BY minutes HAVING COUNT(*) = 1 ORDER BY minutes DESC LIMIT 1;", "Returns no row instead of NULL"], ["SELECT MAX(minutes) AS minutes FROM sessions;", "Ignores uniqueness"]], { skills: [35, 21], alt: "UPDATE sessions SET minutes = 5;" }),
  A("st06-c06:29", "shop", "Bought every category", "Show the name of customers who've bought from every product category.", "Compare a distinct count with the total.", "SELECT c.name FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id GROUP BY c.id, c.name HAVING COUNT(DISTINCT p.category) = (SELECT COUNT(DISTINCT category) FROM products);", [["SELECT c.name FROM customers c JOIN orders o ON o.customer_id = c.id JOIN order_items i ON i.order_id = o.id JOIN products p ON p.id = i.product_id GROUP BY c.id, c.name HAVING COUNT(p.category) = (SELECT COUNT(DISTINCT category) FROM products);", "Counts repeat categories"], ["SELECT c.name FROM customers c;", "Keeps everyone"]], { skills: [33, 21, 32], alt: "UPDATE orders SET customer_id = 1 WHERE id IN (4, 6);" }),
  A("st06-c07:31", "staff", "One department or primary", "Every employee needs a department to report under. Show each employee's id and department_id, with 0 for employees who have none, by stacking two queries.", "Stack two filtered branches.", "SELECT id, department_id FROM employees WHERE department_id IS NOT NULL UNION ALL SELECT id, 0 FROM employees WHERE department_id IS NULL;", [["SELECT id, department_id FROM employees;", "Leaves NULLs"], ["SELECT id, department_id FROM employees WHERE department_id IS NOT NULL;", "Drops employees with none"]], { skills: [38, 9] }),
  A("st06-c08:34", "app", "Minutes as of a date", "Show every user's id as user_id and their total minutes on or before 2024-01-04 as minutes, using 0 if they have none.", "A LEFT JOIN or a subquery with COALESCE.", "SELECT u.id AS user_id, COALESCE((SELECT SUM(s.minutes) FROM sessions s WHERE s.user_id = u.id AND s.session_date <= '2024-01-04'), 0) AS minutes FROM users u;", [["SELECT u.id AS user_id, (SELECT SUM(s.minutes) FROM sessions s WHERE s.user_id = u.id AND s.session_date <= '2024-01-04') AS minutes FROM users u;", "Shows NULL"], ["SELECT u.id AS user_id, COALESCE((SELECT SUM(s.minutes) FROM sessions s WHERE s.user_id = u.id), 0) AS minutes FROM users u;", "Ignores the date"]], { skills: [36, 17], alt: "UPDATE sessions SET session_date = '2024-01-04' WHERE id = 6; UPDATE sessions SET session_date = '2024-01-09' WHERE id = 2;" }),
  A("st06-c09:36", "shop", "Price bands with zeros", "Show exactly three rows, in a column band, for Low (under 5), Mid (5 to 25), and High (over 25), with their product counts as products. Empty bands show 0.", "A UNION ALL keeps every band.", "SELECT 'Low' AS band, COUNT(*) AS products FROM products WHERE price < 5 UNION ALL SELECT 'Mid', COUNT(*) FROM products WHERE price BETWEEN 5 AND 25 UNION ALL SELECT 'High', COUNT(*) FROM products WHERE price > 25;", [["SELECT CASE WHEN price < 5 THEN 'Low' WHEN price <= 25 THEN 'Mid' ELSE 'High' END AS band, COUNT(*) AS products FROM products GROUP BY band;", "An empty band disappears"], ["SELECT 'Low' AS band, COUNT(*) AS products FROM products WHERE price <= 5 UNION ALL SELECT 'Mid', COUNT(*) FROM products WHERE price > 5 AND price < 25 UNION ALL SELECT 'High', COUNT(*) FROM products WHERE price >= 25;", "Puts the limits in the wrong bands"]], { skills: [38, 17], alt: "+ UPDATE products SET price = 25.0 WHERE id = 7; UPDATE products SET price = 5.0 WHERE id = 8;" }),
  A("st06-c10:37", "staff", "Left-behind staff", "Show the id of employees earning under 50000 whose manager_id isn't any current employee's id, sorted by id. Employees with no manager don't count.", "NOT IN against employee ids.", "SELECT id FROM employees WHERE salary < 50000 AND manager_id IS NOT NULL AND manager_id NOT IN (SELECT id FROM employees) ORDER BY id;", [["SELECT id FROM employees WHERE salary < 50000 ORDER BY id;", "Ignores the manager"], ["SELECT id FROM employees WHERE manager_id NOT IN (SELECT id FROM employees) ORDER BY id;", "Ignores salary"]], { skills: [34, 11], alt: "+ UPDATE employees SET manager_id = 88, salary = 49999 WHERE id = 15; UPDATE employees SET manager_id = 88 WHERE id = 12;" }),
  A("st06-c11:39", "school", "Busiest student and top course", "Show two rows in a column named result: the name of the student with the most enrolments, breaking ties alphabetically, then the title of the course with the highest average grade, breaking ties alphabetically.", "Wrap each branch in a FROM subquery.", "SELECT result FROM (SELECT s.name AS result FROM students s JOIN enrolments e ON e.student_id = s.id GROUP BY s.id, s.name ORDER BY COUNT(*) DESC, s.name LIMIT 1) UNION ALL SELECT result FROM (SELECT c.title AS result FROM courses c JOIN enrolments e ON e.course_id = c.id GROUP BY c.id, c.title ORDER BY AVG(e.grade) DESC, c.title LIMIT 1);", [["SELECT s.name AS result FROM students s LIMIT 1;", "Doesn't calculate"], ["SELECT result FROM (SELECT s.name AS result FROM students s JOIN enrolments e ON e.student_id = s.id GROUP BY s.id, s.name ORDER BY COUNT(*), s.name LIMIT 1) UNION ALL SELECT result FROM (SELECT c.title AS result FROM courses c JOIN enrolments e ON e.course_id = c.id GROUP BY c.id, c.title ORDER BY AVG(e.grade), c.title LIMIT 1);", "Sorts the wrong way"]], { skills: [38, 35, 32], ordered: true }),
  A("st06-c12:41", "app", "Most connected", "An invite links two users. Show the id of the user with the most links, counting both sides, as id, with the number as links. Assume one winner, or take the lowest id.", "Stack both sides with UNION ALL, then count.", "SELECT id, COUNT(*) AS links FROM (SELECT id FROM users WHERE referrer_id IS NOT NULL UNION ALL SELECT referrer_id FROM users WHERE referrer_id IS NOT NULL) GROUP BY id ORDER BY links DESC, id LIMIT 1;", [["SELECT referrer_id AS id, COUNT(*) AS links FROM users WHERE referrer_id IS NOT NULL GROUP BY referrer_id ORDER BY links DESC, id LIMIT 1;", "Counts only one side"], ["SELECT id, COUNT(*) AS links FROM (SELECT id FROM users WHERE referrer_id IS NOT NULL UNION SELECT referrer_id FROM users WHERE referrer_id IS NOT NULL) GROUP BY id ORDER BY links DESC, id LIMIT 1;", "UNION removes repeats"]], { skills: [38, 20], alt: "+ UPDATE users SET referrer_id = 8 WHERE id = 9; INSERT INTO users VALUES (10, 'vega', 8, '2024-03-02');" }),
  A("st06-c13:42", "bookshop", "Matching years, unique pairs", "Show the total pages of books that share a year with another book, and whose (author, genre) pair is unique, rounded to 2 decimals, as total_pages.", "Two independent group conditions.", "SELECT ROUND(SUM(pages), 2) AS total_pages FROM books WHERE year IN (SELECT year FROM books GROUP BY year HAVING COUNT(*) > 1) AND (author, genre) IN (SELECT author, genre FROM books GROUP BY author, genre HAVING COUNT(*) = 1);", [["SELECT ROUND(SUM(pages), 2) AS total_pages FROM books WHERE year IN (SELECT year FROM books GROUP BY year HAVING COUNT(*) > 1);", "Ignores the unique pair"], ["SELECT ROUND(SUM(pages), 2) AS total_pages FROM books WHERE (author, genre) IN (SELECT author, genre FROM books GROUP BY author, genre HAVING COUNT(*) = 1);", "Ignores the shared year"]], { skills: [34, 21], alt: "UPDATE books SET year = 2019 WHERE id IN (2, 3); UPDATE books SET author = 'Tom Okafor', genre = 'Science' WHERE id = 5; UPDATE books SET author = 'Mina Rao', genre = 'History' WHERE id = 6;" }),
  A("st06-c14:47", "weather", "Second hottest", "Show the second-highest different temperature as temp_c. If there isn't one, return one row containing NULL.", "A scalar subquery gives NULL for no row.", "SELECT (SELECT DISTINCT temp_c FROM readings ORDER BY temp_c DESC LIMIT 1 OFFSET 1) AS temp_c;", [["SELECT DISTINCT temp_c FROM readings ORDER BY temp_c DESC LIMIT 1 OFFSET 1;", "Returns no row instead of NULL"], ["SELECT (SELECT temp_c FROM readings ORDER BY temp_c DESC LIMIT 1 OFFSET 1) AS temp_c;", "Ties can repeat the highest"]], { skills: [33, 10, 11], alt: "UPDATE readings SET temp_c = 10;" }),
];
